import { useState } from "react"
function P() {
  type U = { readonly name: string }
  const [u, s] = useState<U>({
    name: "Ada",
  })
  const f = () =>
    s({ ...u, name: "Grace" })
  return (
    <button onClick={f}>{u.name}</button>
  )
}
